import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        int n = Integer.parseInt(line.trim());

        StringBuilder sb = new StringBuilder(n);
        while (sb.length() < n) {
            line = br.readLine();
            if (line == null) break;
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) {
                sb.append(st.nextToken());
            }
        }

        String s = sb.toString();

        for (int len = 1; len <= n; len++) {
            if (isValid(s, len)) {
                System.out.println(s.substring(0, len));
                return;
            }
        }
    }

    private static boolean isValid(String s, int len) {
        int n = s.length();
        char[] cur = s.substring(0, len).toCharArray();
        int pos = len;

        while (pos < n) {
            cur = increment(cur);
            int curLen = cur.length;
            if (pos + curLen > n) {
                return false;
            }
            for (int i = 0; i < curLen; i++) {
                if (s.charAt(pos + i) != cur[i]) {
                    return false;
                }
            }
            pos += curLen;
        }

        return pos == n;
    }

    private static char[] increment(char[] num) {
        int len = num.length;
        int i = len - 1;
        while (i >= 0 && num[i] == '9') {
            i--;
        }

        if (i < 0) {
            char[] res = new char[len + 1];
            res[0] = '1';
            for (int j = 1; j <= len; j++) {
                res[j] = '0';
            }
            return res;
        }

        char[] res = new char[len];
        System.arraycopy(num, 0, res, 0, len);
        res[i]++;
        for (int j = i + 1; j < len; j++) {
            res[j] = '0';
        }
        return res;
    }
}
